import re

from pinset.errors import RangeError, VersionError
from pinset.version import BUILD_RE, PRERELEASE_RE, Version

OPERATORS = ("<=", ">=", "<", ">", "=", "^", "~")
WILDCARDS = ("x", "X", "*")
NUMBER_RE = re.compile(r"0|[1-9][0-9]*")
SPACES_RE = re.compile(r"[ \t]+")
FIRST_CHARS = "0123456789xX*"


class _Partial:
    __slots__ = ("numbers", "prerelease", "build")

    def __init__(self, numbers, prerelease, build):
        self.numbers = numbers  # leading numeric parts only
        self.prerelease = prerelease
        self.build = build

    @property
    def full(self):
        return len(self.numbers) == 3

    def version(self, prerelease=None):
        nums = list(self.numbers) + [0] * (3 - len(self.numbers))
        pre = self.prerelease if prerelease is None else prerelease
        return Version(nums[0], nums[1], nums[2], pre)

    def upper(self):
        """The lowest version of the block above the one this partial names (prerelease `0`), or None."""
        count = len(self.numbers)
        if count == 0:
            return None
        nums = list(self.numbers)
        nums[-1] += 1
        nums += [0] * (3 - count)
        return Version(nums[0], nums[1], nums[2], ("0",))


def _parse_partial(text: str) -> _Partial:
    def bad():
        return RangeError("bad-version", f"not a version: {text!r}")

    head, plus, build = text.partition("+")
    core, dash, pre = head.partition("-")
    parts = core.split(".")
    if not 1 <= len(parts) <= 3:
        raise bad()
    numbers = []
    wild = False
    for part in parts:
        if part in WILDCARDS:
            wild = True
        elif NUMBER_RE.fullmatch(part) and not wild:
            numbers.append(int(part))
        else:
            raise bad()
    if dash or plus:
        if len(numbers) != 3:
            raise bad()
        if dash and not PRERELEASE_RE.fullmatch(pre):
            raise bad()
        if plus and not BUILD_RE.fullmatch(build):
            raise bad()
    return _Partial(tuple(numbers), tuple(pre.split(".")) if dash else (), build)


class _Alternative:
    def __init__(self):
        self.checks = []  # (operator, Version or None); operator "none" never holds
        self.carriers = set()  # releases named with a prerelease

    def add(self, op, version, carries=False):
        self.checks.append((op, version))
        if carries and version is not None and version.prerelease:
            self.carriers.add(version.release)

    def none(self):
        self.checks.append(("none", None))

    def test(self, version: Version) -> bool:
        for op, bound in self.checks:
            if op == "none":
                return False
            if op == ">=" and not version >= bound:
                return False
            if op == ">" and not version > bound:
                return False
            if op == "<" and not version < bound:
                return False
            if op == "<=" and not version <= bound:
                return False
            if op == "=" and not version == bound:
                return False
