class Range:
    def __init__(self, text: str, alternatives, exact: bool):
        self.text = text
        self.alternatives = alternatives
        self.exact = exact

    def test(self, version: Version) -> bool:
        """True when `version` satisfies the range."""
        return any(alt.test(version) for alt in self.alternatives)

    def is_exact(self) -> bool:
        """True for a range that names one version (docs/ranges.md, section 10)."""
        return self.exact

    def __str__(self):
        return self.text


def parse_range(text: str) -> Range:
    if not isinstance(text, str):
        raise RangeError("bad-range", f"a range is a string, not {type(text).__name__}")
    if not text.strip(" \t"):
        raise RangeError("bad-range", "empty range")
    chunks = text.split("||")
    if any(not chunk.strip(" \t") for chunk in chunks):
        raise RangeError("bad-range", f"empty alternative in {text!r}")
    alternatives = [_read_alternative(chunk, text) for chunk in chunks]
    exact = False
    if len(chunks) == 1:
        tokens = SPACES_RE.split(chunks[0].strip(" \t"))
        if len(tokens) == 1:
            body = tokens[0][1:] if tokens[0].startswith("=") else tokens[0]
            exact = len(alternatives[0].checks) == 1 and alternatives[0].checks[0][0] == "=" and _is_full(body)
    return Range(text, alternatives, exact)


def _is_full(body: str) -> bool:
    try:
        Version.parse(body)
    except VersionError:
        return False
    return True
