    return _Partial(tuple(numbers), tuple(pre.split(".")) if dash else (), build)


class _Alternative:
    def __init__(self):
        self.checks = []  # (operator, Version or None); operator "none" never holds
        self.carriers = set()  # releases named with a prerelease

    def add(self, op, version, carries=False):
        self.checks.append((op, version))
        if carries and version is not None and version.prerelease:
            self.carriers.add(version.release)

    def none(self):
        self.checks.append(("none", None))

    def test(self, version: Version) -> bool:
        for op, bound in self.checks:
            if op == "none":
                return False
            if op == ">=" and not version >= bound:
                return False
            if op == ">" and not version > bound:
                return False
            if op == "<" and not version < bound:
                return False
            if op == "<=" and not version <= bound:
                return False
            if op == "=" and not version == bound:
                return False
        return not version.is_prerelease() or version.release in self.carriers


def _comparator(alt: _Alternative, op: str, partial: _Partial):
    count = len(partial.numbers)
    if op == "^" or op == "~":
        if count == 0:
            return
        low = partial.version()
        if op == "^" or count == 1:
            high = Version(partial.numbers[0] + 1, 0, 0, ("0",))
        else:
            high = Version(partial.numbers[0], partial.numbers[1] + 1, 0, ("0",))
        alt.add(">=", low, True)
        alt.add("<", high)
        return
    if partial.full:
        alt.add(op or "=", partial.version(), True)
        return
    op = op or "="
    low = partial.version()
    high = partial.upper()
    if op == "=":
        if count:
            alt.add(">=", low)
            alt.add("<", high)
    elif op == ">=":
        if count:
            alt.add(">=", low)
    elif op == ">":
        if count:
            alt.add(">=", Version(*high.release))
        else:
            alt.none()
    elif op == "<":
        if count:
            alt.add("<", Version(*low.release, ("0",)))
        else:
            alt.none()
    elif op == "<=":
        if count:
            alt.add("<", high)


def _hyphen(low: _Partial, high: _Partial) -> _Alternative:
    alt = _Alternative()
    if low.numbers:
        alt.add(">=", low.version(), True)
    if high.full:
        alt.add("<=", high.version(), True)
    elif high.numbers:
        alt.add("<", high.upper())
    return alt


def _starts_with_operator(token: str) -> bool:
    return token.startswith(OPERATORS)


def _check_shape(token: str, text: str):
    if token[:1] not in FIRST_CHARS or not token:
        raise RangeError("bad-range", f"unsupported range {text!r}")


def _read_alternative(chunk: str, text: str) -> _Alternative:
    tokens = SPACES_RE.split(chunk.strip(" \t"))
    if "-" in tokens:
        if len(tokens) != 3 or tokens[1] != "-":
            raise RangeError("bad-range", f"misplaced '-' in {text!r}")
        low_text, _, high_text = tokens
        for end in (low_text, high_text):
            if _starts_with_operator(end):
                raise RangeError("bad-range", f"operator in a hyphen range {text!r}")
            _check_shape(end, text)
        return _hyphen(_parse_partial(low_text), _parse_partial(high_text))
    split = []
    for token in tokens:
        op = next((o for o in OPERATORS if token.startswith(o)), "")
        rest = token[len(op):]
        _check_shape(rest, text)
        split.append((op, rest))
    alt = _Alternative()
    for op, rest in split:
        _comparator(alt, op, _parse_partial(rest))
    return alt


class Range:
    def __init__(self, text: str, alternatives, exact: bool):
        self.text = text
        self.alternatives = alternatives
        self.exact = exact

    def test(self, version: Version) -> bool:
        """True when `version` satisfies the range."""
        return any(alt.test(version) for alt in self.alternatives)

    def is_exact(self) -> bool:
        """True for a range that names one version (docs/ranges.md, section 10)."""
        return self.exact

    def __str__(self):
        return self.text


def parse_range(text: str) -> Range:
    if not isinstance(text, str):
        raise RangeError("bad-range", f"a range is a string, not {type(text).__name__}")
    if not text.strip(" \t"):
        raise RangeError("bad-range", "empty range")
    chunks = text.split("||")
    if any(not chunk.strip(" \t") for chunk in chunks):
        raise RangeError("bad-range", f"empty alternative in {text!r}")
    alternatives = [_read_alternative(chunk, text) for chunk in chunks]
    exact = False
    if len(chunks) == 1:
        tokens = SPACES_RE.split(chunks[0].strip(" \t"))
        if len(tokens) == 1:
            body = tokens[0][1:] if tokens[0].startswith("=") else tokens[0]
            exact = len(alternatives[0].checks) == 1 and alternatives[0].checks[0][0] == "=" and _is_full(body)
    return Range(text, alternatives, exact)


def _is_full(body: str) -> bool:
    try:
        Version.parse(body)
    except VersionError:
        return False
    return True
